export type GetCrmMembersData = {
    body?: never;
    path?: never;
    query?: {
        /**
         * Page number
         */
        page?: number;
        /**
         * Items per page
         */
        limit?: number;
        /**
         * Search query (name, member number, phone, email)
         */
        search?: string;
        /**
         * Search matching mode. substring (default) = current behaviour; prefix = prefix match on name/kana/email/phone, exact on member number and legacy code
         */
        match_mode?: 'substring' | 'prefix';
        /**
         * Filter by contract type (array)
         */
        contract_type?: Array<'regular' | 'one_day_member' | 'family'> | null;
        /**
         * Filter by status (array)
         */
        status?: Array<'provisional' | 'active' | 'pending_suspended' | 'suspended' | 'pending_withdrawal' | 'withdrawal_pending_processing' | 'withdrawn' | 'forced_withdrawal'> | null;
        /**
         * Filter by brand group (array). The A-01 「ブランド」 dropdown maps here 1:1
         */
        brand_group?: Array<'joyfit' | 'fit365'> | null;
        /**
         * Filter by store ID (array)
         */
        store_id?: Array<string> | null;
        /**
         * Filter by main contract (plan) id (array)
         */
        main_contract_id?: Array<string> | null;
        /**
         * Inclusive lower bound on the join date (入会日)
         */
        enrolled_from?: string;
        /**
         * Inclusive upper bound on the join date (入会日)
         */
        enrolled_to?: string;
        /**
         * Inclusive lower bound on the last-entry date
         */
        last_entry_from?: string;
        /**
         * Inclusive upper bound on the last-entry date
         */
        last_entry_to?: string;
        /**
         * Keep members that have never entered even though a last-entry bound is set. The 「3週間以上来館なし」/「1ヶ月以上来館なし」 buckets must send this, since never-visited members carry the highest churn risk (A-01 FR-001). Ignored when neither bound is set
         */
        include_never_entered?: boolean | null;
        /**
         * Filter by the promotion code used at enrollment. Exact match on the campaign master's `code` — not the campaign name (G-06 FR-011)
         */
        promo_code?: string;
        /**
         * Filter by an uncleared manual gate stop. The screen's 「ゲートストップ」 status option sends `has_gate_stop=true` and no `status`, because gate stop is orthogonal to member status
         */
        has_gate_stop?: boolean | null;
        /**
         * Filter by unpaid status
         */
        has_unpaid?: boolean | null;
        /**
         * Sort field
         */
        sort_by?: 'member_number' | 'joined_at' | 'last_visit_date' | 'name' | 'status';
        /**
         * Sort order
         */
        sort_order?: 'asc' | 'desc';
    };
    url: '/crm/members';
};

